import type { FloodReport, RoadIncident, RoadRiskLevel, Tile } from "./types";

/**
 * Evaluates the flood risk level of an actual OSM road segment.
 * Checks official road closures, depth-weighted crowdsourced reports, and 100m² tile telemetry.
 */
export function evaluateOsmRoadRisk(
  road: OsmRoadSegment,
  tileMap: Map<string, Tile>,
  incidents: RoadIncident[],
  reports: FloodReport[],
): {
  riskLevel: RoadRiskLevel;
  severityScore: number;
  reason: string;
} {
  // 1. Check official road closures
  for (const inc of incidents) {
    const isClosedAll = inc.status === "ClosedAllTraffic";
    const isClosedSmall = inc.status === "ClosedSmallVehicles";
    if (!isClosedAll && !isClosedSmall) continue;

    const incTile = tileMap.get(inc.tileId);
    const inTile = road.tileIds.includes(inc.tileId);
    let isNear = false;
    if (incTile) {
      isNear = road.coordinates.some(([lat, lng]) => {
        const dLat = (lat - incTile.centerLat) * 111000;
        const dLng = (lng - incTile.centerLng) * 105000;
        return dLat * dLat + dLng * dLng < 220 * 220;
      });
    }

    if (inTile || isNear) {
      const desc = inc.description || inc.notes || "Official roadblock";
      if (isClosedAll) {
        return {
          riskLevel: "Closed",
          severityScore: 100,
          reason: `Road closed by authorities: ${desc}`,
        };
      }
      return {
        riskLevel: "Critical",
        severityScore: 85,
        reason: `Closed to light vehicles: ${desc}`,
      };
    }
  }

  // 2. Check nearby verified citizen reports
  for (const r of reports) {
    if (r.status === "Dismissed") continue;
    const isNear = road.coordinates.some(([lat, lng]) => {
      const dLat = (lat - r.lat) * 111000;
      const dLng = (lng - r.lng) * 105000;
      return dLat * dLat + dLng * dLng < 50 * 50;
    });

    if (isNear) {
      if (r.status === "Verified" && r.severityUser === "WaistPlus") {
        return {
          riskLevel: "Critical",
          severityScore: 88,
          reason: `Municipal-verified waist-deep inundation: ${r.description}`,
        };
      }
      if (r.severityUser === "WaistPlus" || (r.status === "Verified" && r.severityUser === "Knees")) {
        return {
          riskLevel: "High",
          severityScore: 65,
          reason: `Deep waterlogged street: ${r.description}`,
        };
      }
    }
  }

  // 3. Check tile flood severity
  let maxScore = 0;
  let maxTile: Tile | null = null;
  for (const tid of road.tileIds) {
    const t = tileMap.get(tid);
    if (t && t.currentSeverityScore > maxScore) {
      maxScore = t.currentSeverityScore;
      maxTile = t;
    }
  }

  // If road is on the edge of the grid or has empty tileIds, resolve the nearest surveyed block
  if (!maxTile && road.coordinates.length > 0) {
    const [rLat, rLng] = road.coordinates[0];
    let bestDist = Infinity;
    for (const t of tileMap.values()) {
      const dLat = (t.centerLat - rLat) * 111000;
      const dLng = (t.centerLng - rLng) * 105000;
      const d = dLat * dLat + dLng * dLng;
      if (d < 350 * 350 && d < bestDist) {
        bestDist = d;
        maxTile = t;
        maxScore = t.currentSeverityScore;
      }
    }
  }

  if (!maxTile) {
    return {
      riskLevel: "Low",
      severityScore: 0,
      reason: "Normal conditions – Safe to pass",
    };
  }

  if (maxScore >= 70) {
    return {
      riskLevel: "Critical",
      severityScore: maxScore,
      reason: `Critical flood risk (${maxScore}/100) in ${maxTile.locality}`,
    };
  }
  if (maxScore >= 40) {
    return {
      riskLevel: "High",
      severityScore: maxScore,
      reason: `High flood risk (${maxScore}/100) in ${maxTile.locality}`,
    };
  }
  if (maxScore >= 20) {
    return {
      riskLevel: "Moderate",
      severityScore: maxScore,
      reason: `Moderate water accumulation (${maxScore}/100) in ${maxTile.locality}`,
    };
  }

  return {
    riskLevel: "Low",
    severityScore: maxScore,
    reason: `Normal conditions (${maxScore}/100) – Safe to pass`,
  };
}
